/**
 * Checks if a value is a string.
 *
 * @param value - Value to check.
 */
export declare const isString: (value: unknown) => value is string;
/**
 * Checks if a value is not undefined or null.
 *
 * @param value - Value.
 */
export declare const isset: <T>(value: T) => value is NonNullable<T>;
/**
 * Checks if a value is an Element.
 *
 * @param value - Any value.
 */
export declare const isElement: (value: unknown) => value is Element;
/**
 * Checks if a value is a number.
 *
 * @param value - Any value.
 * @returns - value is a number.
 */
export declare const isNumber: (value: unknown) => boolean;
/**
 * Checks if a value is a function.
 *
 * @param value - Any value.
 * @returns - value is a function.
 */
export declare const isFunction: (value: unknown) => value is Function;
